#include <iostream>
#include <fstream>

int main() {
    std::ofstream salida{"muestra_lgp.txt"};
    if (!salida) {
        std::cout << "Output file open error";
        return 1;
    }
    salida << "2 5";
    salida.close();
    if (!salida) {
        std::cout << "Write error";
        return 1;
    }
    std::ifstream entrada{"muestra_lgp.txt"};
    if (!entrada) {
        std::cout << "Input file open error";
        return 1;
    }
    int primero{0};
    int segundo{0};
    if (!(entrada >> primero >> segundo)) {
        std::cout << "Invalid format";
        return 1;
    }
    std::cout << "Total=" << primero + segundo;
    return 0;
}

